spec.setup_code:
function rng(seed){var a=seed;return function(){a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var K=80,N=12,PERIOD=9,RUN=7,BR=0.1;
function G(s){return 0.2+0.8*Math.exp(-s/0.1)+0.45*Math.exp(-Math.pow((s-0.7)/0.15,2));}
var sd=0.05;
while(sd<0.9&&G(sd+0.005)<G(sd)){sd+=0.005;}
var tys=[0.12,0.25,0.75,0.88];
var base=[];
var r0=rng(7);
for(var i=0;i<N;i++){base.push({y0:0.5+(r0()-0.5)*0.4,xj:(r0()-0.5)*0.05,ty:tys[i%4]+(r0()-0.5)*0.08,seed:100+i});}
function sim(mode){
 var out=[];
 for(var i=0;i<N;i++){
 var b=base[i],R=rng(b.seed),y=b.y0,p=[];
 for(var k=0;k<=K;k++){
 var s=k/K;
 p.push({x:0.06+b.xj+0.84*Math.pow(s,0.9),y:y});
 var w=0.5*Math.exp(-s/0.2)+0.1;
 var gs=Math.exp(-Math.pow((y-0.5)/w,2));
 var g=G(s);
 var pull;
 if(mode===0){pull=0.1*g*gs;}else{pull=(s<sd)?-0.05*g*gs:0.1*g*gs;}
 var c=0.03+0.06*s;
 y+=(b.ty-y)*c+pull*(0.5-y)+(R()-0.5)*0.03*(1-s);
 if(y<0.03)y=0.03;if(y>0.97)y=0.97;
 }
 out.push(p);
 }
 return out;
}
var paths=[sim(0),sim(1)];
var caught=[0,0];
for(var m=0;m<2;m++){for(var i=0;i<N;i++){var e=paths[m][i][K];if(Math.abs(e.y-0.5)<BR)caught[m]++;}}
function pos(p,s){var f=s*K,k=Math.min(K-1,Math.floor(f)),u=f-k;return{x:p[k].x+(p[k+1].x-p[k].x)*u,y:p[k].y+(p[k+1].y-p[k].y)*u,k:k};}
function panel(ctx,mode,px,py,pw,ph,s){
 ctx.strokeStyle='#1a1a1d';ctx.lineWidth=1;ctx.strokeRect(px,py,pw,ph);
 var bx=px+0.9*pw,by=py+0.5*ph,br=BR*ph;
 ctx.fillStyle='rgba(225,29,72,0.12)';ctx.beginPath();ctx.arc(bx,by,br*1.9,0,6.2832);ctx.fill();
 ctx.fillStyle='rgba(225,29,72,0.25)';ctx.beginPath();ctx.arc(bx,by,br,0,6.2832);ctx.fill();
 ctx.strokeStyle='#e11d48';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(bx,by,br,0,6.2832);ctx.stroke();
 ctx.fillStyle='#e11d48';ctx.font='12px sans-serif';ctx.textAlign='right';ctx.fillText('memorised basin',px+pw-6,by-br*1.9-4);
 for(var j=0;j<tys.length;j++){
 ctx.fillStyle='rgba(5,150,105,0.25)';ctx.beginPath();ctx.arc(bx,py+tys[j]*ph,br*0.6,0,6.2832);ctx.fill();
 ctx.strokeStyle='#059669';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(bx,py+tys[j]*ph,br*0.6,0,6.2832);ctx.stroke();
 }
 ctx.textAlign='left';
 for(var i=0;i<N;i++){
 var p=paths[mode][i],q=pos(p,s);
 var col=(mode===1&&q.k<sd*K)?'#0284c7':'#7c3aed';
 ctx.lineWidth=1.4;
 for(var k=0;k<=q.k;k++){
 var x2=(k===q.k)?q.x:p[k+1].x,y2=(k===q.k)?q.y:p[k+1].y;
 ctx.strokeStyle=(mode===1&&k<sd*K)?'rgba(2,132,199,0.55)':'rgba(124,58,237,0.55)';
 ctx.beginPath();ctx.moveTo(px+p[k].x*pw,py+p[k].y*ph);ctx.lineTo(px+x2*pw,py+y2*ph);ctx.stroke();
 }
 ctx.fillStyle=col;ctx.beginPath();ctx.arc(px+q.x*pw,py+q.y*ph,3.2,0,6.2832);ctx.fill();
 }
 if(s>=0.999){
 ctx.fillStyle=caught[mode]>N/2?'#e11d48':'#059669';ctx.font='13px sans-serif';
 ctx.fillText('in basin: '+caught[mode]+' / '+N,px+8,py+ph-8);
 }
}
return {draw:function(ctx,width,height,time,dt){
 ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);
 var tt=time%PERIOD;var s=Math.min(1,tt/RUN);
 var m=14,gap=14;
 var pw=(width-2*m-gap)/2,py=44,ph=Math.max(80,height*0.5-30);
 ctx.fillStyle='#1a1a1d';ctx.font='13px sans-serif';ctx.textAlign='left';
 ctx.fillText('Standard CFG from t = T',m,34);
 ctx.fillText('Delayed CFG: opposite guidance until DTP',m+pw+gap,34);
 panel(ctx,0,m,py,pw,ph,s);
 panel(ctx,1,m+pw+gap,py,pw,ph,s);
 ctx.fillStyle='#1a1a1d';ctx.font='12px sans-serif';
 ctx.fillText('x_T (noise)',m+4,py+ph+14);
 ctx.textAlign='right';ctx.fillText('x_0 (sample)',m+pw-4,py+ph+14);ctx.fillText('x_0 (sample)',m+2*pw+gap-4,py+ph+14);
 ctx.textAlign='left';ctx.fillText('x_T (noise)',m+pw+gap+4,py+ph+14);
 var cx=m+30,cw=width-2*m-40,cy=py+ph+36,ch=Math.max(40,height-cy-34);
 var gmax=1.15;
 function X(u){return cx+u*cw;}
 function Y(g){return cy+ch-(g/gmax)*ch;}
 ctx.fillStyle='rgba(2,132,199,0.10)';ctx.fillRect(X(0),cy,sd*cw,ch);
 ctx.strokeStyle='#1a1a1d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx,cy+ch);ctx.lineTo(cx+cw,cy+ch);ctx.stroke();
 ctx.strokeStyle='#d97706';ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(X(sd),cy);ctx.lineTo(X(sd),cy+ch);ctx.stroke();ctx.setLineDash([]);
 ctx.fillStyle='#d97706';ctx.fillText('DTP (first local min)',X(sd)+5,cy+10);
 ctx.fillStyle='#0284c7';ctx.fillText('CFG off / negative',X(0)+4,cy+ch-5);
 ctx.strokeStyle='#7c3aed';ctx.lineWidth=2;ctx.beginPath();
 for(var i=0;i<=100;i++){var u=i/100;if(i===0)ctx.moveTo(X(u),Y(G(u)));else ctx.lineTo(X(u),Y(G(u)));}
 ctx.stroke();
 ctx.strokeStyle='#1a1a1d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(X(s),cy);ctx.lineTo(X(s),cy+ch);ctx.stroke();
 ctx.fillStyle='#e11d48';ctx.beginPath();ctx.arc(X(s),Y(G(s)),4,0,6.2832);ctx.fill();
 ctx.fillStyle='#1a1a1d';ctx.textAlign='left';ctx.fillText('||ε(x,c) − ε(x,∅)||',m,cy-6);
 ctx.textAlign='right';ctx.fillText('t: T → 0',cx+cw,cy+ch+14);
 ctx.textAlign='left';
 var tv=(1-s);
 var st=(s<sd)?'right panel: Opposite Guidance, pushing away from basin':'right panel: CFG switched on after DTP';
 ctx.fillText('t/T = '+tv.toFixed(2)+'   left: CFG on since t = T   |   '+st,m,height-8);
}};
